.crypto-coin {
  position: absolute; width: 40px; height: 40px;
  background: radial-gradient(circle, #ffd700, #b8860b);
  border: 2px solid #fffacd; border-radius: 50%;
  box-shadow: 0 0 15px rgba(255, 215, 0, 0.6), inset 0 0 10px rgba(0,0,0,0.5);
  display: flex; align-items: center; justify-content: center;
  color: #fff; font-weight: bold; font-family: sans-serif;
  animation: floatCoin 6s infinite linear, spinY 3s infinite linear;
}
@keyframes floatCoin {
  0% { transform: translateY(0); opacity: 0; }
  50% { opacity: 1; }
  100% { transform: translateY(-150px); opacity: 0; }
}
@keyframes spinY { 100% { transform: rotateY(360deg); } }

