const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;position:relative;background:transparent;overflow:hidden;perspective:800px;';

const symbols = ['₿', 'Ξ', '$', '₹'];

for(let i=0; i<8; i++) {
  const coin = document.createElement('div');
  coin.className = 'crypto-coin';
  coin.innerText = symbols[Math.floor(Math.random() * symbols.length)];
  coin.style.left = `${Math.random() * 90}%`;
  coin.style.top = `${50 + Math.random() * 50}%`;
  coin.style.animationDelay = `${Math.random() * 5}s`;
  c.appendChild(coin);
}
